<?php
/**
 * Plain-PHP tests for the WordPress-independent classes. Run: php tests/run.php
 * The signature fixture is generated by packages/server/src/connector.test.ts so both sides stay in sync.
 * CLI test harness, not shipped with the plugin.
 *
 * @package SceneFlow
 */

// phpcs:ignoreFile

define( 'SCENEFLOW_TESTING', true );
// The classes under test guard against direct access with ABSPATH; the harness stands in for WordPress.
define( 'ABSPATH', dirname( __DIR__ ) . '/' );
require __DIR__ . '/../includes/class-sceneflow-signature.php';
require __DIR__ . '/../includes/class-sceneflow-config.php';

$passed = 0;
/**
 * Asserts a condition.
 *
 * @param bool   $cond Condition.
 * @param string $name Test name.
 */
function sf_assert( $cond, $name ) {
	global $passed;
	if ( ! $cond ) {
		fwrite( STDERR, "FAIL: {$name}\n" );
		exit( 1 );
	}
	++$passed;
}

$fixture_path = __DIR__ . '/fixtures/signature.json';
sf_assert( file_exists( $fixture_path ), 'fixture exists (run pnpm --filter @sceneflow/server test first)' );
$fx = json_decode( file_get_contents( $fixture_path ), true );

// --- signature interop with Node ---
sf_assert( SceneFlow_Signature::canonical( $fx['method'], $fx['route'], $fx['timestamp'], $fx['nonce'], $fx['body'] ) === $fx['canonical'], 'canonical string matches Node' );
sf_assert( hash( 'sha256', $fx['body'] ) === $fx['bodySha256'], 'body hash matches' );
sf_assert( SceneFlow_Signature::sign( $fx['secret'], $fx['method'], $fx['route'], $fx['timestamp'], $fx['nonce'], $fx['body'] ) === $fx['signature'], 'signature matches Node' );
$ok = SceneFlow_Signature::verify( $fx['secret'], $fx['method'], $fx['route'], (string) $fx['timestamp'], $fx['nonce'], $fx['body'], $fx['signature'], $fx['timestamp'] + 10 );
sf_assert( true === $ok['ok'], 'verify ok' );
$bad = SceneFlow_Signature::verify( $fx['secret'], $fx['method'], $fx['route'], (string) $fx['timestamp'], $fx['nonce'], $fx['body'] . ' ', $fx['signature'], $fx['timestamp'] );
sf_assert( false === $bad['ok'] && 'bad_signature' === $bad['error'], 'tampered body rejected' );
$stale = SceneFlow_Signature::verify( $fx['secret'], $fx['method'], $fx['route'], (string) $fx['timestamp'], $fx['nonce'], $fx['body'], $fx['signature'], $fx['timestamp'] + 301 );
sf_assert( 'stale_timestamp' === $stale['error'], 'stale timestamp rejected' );
$wrong = SceneFlow_Signature::verify( 'other', $fx['method'], $fx['route'], (string) $fx['timestamp'], $fx['nonce'], $fx['body'], $fx['signature'], $fx['timestamp'] );
sf_assert( 'bad_signature' === $wrong['error'], 'wrong secret rejected' );
$nonce = SceneFlow_Signature::verify( $fx['secret'], $fx['method'], $fx['route'], (string) $fx['timestamp'], 'short', $fx['body'], $fx['signature'], $fx['timestamp'] );
sf_assert( 'invalid_nonce' === $nonce['error'], 'short nonce rejected' );
$malformed = SceneFlow_Signature::verify( $fx['secret'], $fx['method'], $fx['route'], (string) $fx['timestamp'], $fx['nonce'], $fx['body'], 'zz', $fx['timestamp'] );
sf_assert( 'invalid_signature' === $malformed['error'], 'malformed signature rejected' );

// --- config validation ---
function sf_config( $src, $schema = '1.0' ) {
	return json_encode(
		array(
			'schemaVersion' => $schema,
			'projectId'     => 'p1',
			'version'       => 1,
			'scenes'        => array( array( 'id' => 's1', 'layers' => array( array( 'type' => 'image', 'src' => $src ) ) ) ),
		)
	);
}
$good = sf_config( 'https://cdn.example/x.jpg' );
sf_assert( true === SceneFlow_Config::validate( $good, 'p1' )['ok'], 'valid config accepted' );
sf_assert( 'project_mismatch' === SceneFlow_Config::validate( $good, 'p2' )['error'], 'project id mismatch rejected' );
sf_assert( 'unsupported_schema' === SceneFlow_Config::validate( sf_config( 'https://x.y/z', '2.0' ), 'p1' )['error'], 'major version 2 rejected' );
sf_assert( 'invalid_json' === SceneFlow_Config::validate( '{nope', 'p1' )['error'], 'invalid json rejected' );
sf_assert( 'too_large' === SceneFlow_Config::validate( str_repeat( 'x', 524289 ), 'p1' )['error'], 'oversize rejected' );
sf_assert( 'unsafe_url' === SceneFlow_Config::validate( sf_config( 'javascript:alert(1)' ), 'p1' )['error'], 'javascript: url rejected' );
sf_assert( 'unsafe_url' === SceneFlow_Config::validate( sf_config( ' data:text/html,hi' ), 'p1' )['error'], 'data: url rejected' );
sf_assert( 'unsafe_url' === SceneFlow_Config::validate( sf_config( 'JavaScript:alert(1)' ), 'p1' )['error'], 'mixed-case javascript: rejected' );
sf_assert( 'missing_scenes' === SceneFlow_Config::validate( '{"schemaVersion":"1.0","projectId":"p1"}', 'p1' )['error'], 'missing scenes rejected' );

// --- helpers ---
// Serving a config must not turn empty objects into arrays (PHP assoc-array round trip); the player rejects `"style":[]`.
$roundtrip = '{"schemaVersion":"1.0","projectId":"p1","scenes":[{"id":"s","layers":[{"id":"l","type":"hotspot","style":{},"content":{},"responsive":{"tablet":{}}}]}],"fonts":{"google":[]}}';
sf_assert( json_encode( SceneFlow_Config::decode_for_output( $roundtrip ) ) === $roundtrip, 'served config keeps {} as {} and [] as []' );
sf_assert( null === SceneFlow_Config::decode_for_output( '{nope' ), 'unreadable stored config decodes to null' );

sf_assert( SceneFlow_Config::is_valid_id( 'abc-123_X' ) && ! SceneFlow_Config::is_valid_id( 'a b' ) && ! SceneFlow_Config::is_valid_id( str_repeat( 'a', 65 ) ), 'id validation' );
sf_assert( SceneFlow_Config::is_valid_selector( '#hero > .wp-block-cover' ) && ! SceneFlow_Config::is_valid_selector( '<img onerror=x>' ) && ! SceneFlow_Config::is_valid_selector( '' ), 'selector validation' );
sf_assert( SceneFlow_Config::is_valid_css_length( '720px' ) && SceneFlow_Config::is_valid_css_length( '100%' ) && SceneFlow_Config::is_valid_css_length( '37.5rem' ), 'css length accepted' );
sf_assert( ! SceneFlow_Config::is_valid_css_length( '720px;background:url(x)' ) && ! SceneFlow_Config::is_valid_css_length( 'expression(1)' ) && ! SceneFlow_Config::is_valid_css_length( '' ) && ! SceneFlow_Config::is_valid_css_length( 12 ), 'css injection rejected' );

echo "OK: {$passed} assertions passed\n";
